/**
 * Mini Ophthalmosaurus (Tipo Agua) — Versión Chibi / Cría compañera de dinosaurio.
 * Basado en el arte oficial de Dinosaur King:
 *   assets/dinos/arte/agua/ophthalmosaurus_izq.webp
 *
 * Características anatómicas del Ophthalmosaurus (Ictiosaurio marino):
 *   - Cuerpo fusiforme e hidrodinámico en forma de huso/delfín compacto y robusto.
 *   - Ojos escleróticos gigantescos (el animal con los ojos más grandes en proporción a su cuerpo),
 *     con un prominente anillo esclerótico óseo protector, pupila profunda y destellos anime brillantes.
 *   - Rostro alargado y estilizado como pico de delfín con mandíbula articulada y finos dientes cónicos.
 *   - Aleta dorsal triangular estilizada en el lomo y aleta caudal vertical semilunar (en media luna).
 *   - 4 aletas alares hidrodinámicas (2 pectorales y 2 pelvianas) cerradas herméticamente en cúpula (cero huecos).
 *   - Malla 100% cerrada y hermética (watertight).
 *   - Proyección lateral de la textura oficial con dorso azul petróleo / verde azulado marino (0x3c555c),
 *     vientre plateado blanco puro (0xf2f6f7) y anillo esclerótico marfil claro.
 *   - Esqueleto y animaciones subacuáticas (Reposo flotando, Nadar pelágico ondulatorio, Rugir / Ataque marino).
 */
registrarMalla({
  id: "mini_ophthalmosaurus",
  categoria: "mini dino",
  nombre: "Mini Ophthalmosaurus (Agua)",
  icono: "🐬",
  origen: "assets/dinos/arte/agua/ophthalmosaurus_izq.webp",

  construir(M) {
    const g = new THREE.Group();
    const LADOS = [-1, 1];
    const L = (s) => (s > 0 ? "I" : "D");
    const V = (x, y, z) => new THREE.Vector3(x, y, z);
    const grad = Math.PI / 180;
    const cr = (p0, p1, p2, p3, t) => 0.5 * ((2 * p1) + (-p0 + p2) * t
      + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t + (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);

    // ---------------- UTILIDADES GEOMÉTRICAS ----------------
    const suave = (a, b, x) => {
      const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
      return t * t * (3 - 2 * t);
    };

    function rejilla(pos, cols, rows, nombre) {
      const idx = [];
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const a = r * (cols + 1) + c;
          const b = a + cols + 1;
          idx.push(a, b, a + 1, b, b + 1, a + 1);
        }
      }
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.Float32BufferAttribute(pos, 3));
      geo.setIndex(idx);
      geo.computeVertexNormals();
      return M.pieza(geo, nombre, cols, rows);
    }

    function bloque(x, y, z, rx, ry, rz, curva = 0.5, nombre = "Bloque", segA = 12, segB = 10) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const pos = [];
      for (let r = 0; r <= sH; r++) {
        const v = r / sH;
        const th = (v - 0.5) * Math.PI;
        const cTh = Math.cos(th);
        const sTh = Math.sin(th);
        const ryCurva = Math.pow(Math.abs(cTh), curva);
        const yN = ry * Math.sign(sTh) * Math.pow(Math.abs(sTh), curva);
        for (let c = 0; c <= sW; c++) {
          const u = c / sW;
          const fi = u * Math.PI * 2;
          const sFi = Math.sin(fi);
          const cFi = Math.cos(fi);
          const xN = rx * ryCurva * Math.sign(cFi) * Math.pow(Math.abs(cFi), curva);
          const zN = rz * ryCurva * Math.sign(sFi) * Math.pow(Math.abs(sFi), curva);
          pos.push(x + xN, y + yN, z + zN);
        }
      }
      return M.coserNormales(rejilla(pos, sW, sH, nombre));
    }

    function punta(camino, rBase, nombre = "Punta", segL = 10, segR = 8) {
      const c = M.curva(camino);
      const sL = M.seg(segL, 6);
      const sR = M.seg(segR, 6);
      const geo = new THREE.TubeGeometry(c, sL, 1, sR, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();
      for (let i = 0; i <= sL; i++) {
        const t = i / sL;
        c.getPointAt(t, P);
        const r = rBase * Math.pow(1 - t, 0.85);
        for (let j = 0; j <= sR; j++) {
          const k = i * (sR + 1) + j;
          pos.setXYZ(k,
            P.x + (pos.getX(k) - P.x) * r,
            P.y + (pos.getY(k) - P.y) * r,
            P.z + (pos.getZ(k) - P.z) * r
          );
        }
      }
      return M.coserNormales(M.pieza(geo, nombre, sR, sL));
    }

    function toroide(radioMayor, radioMenor, nombre = "Toroide", segU = 24, segV = 12) {
      const sU = M.seg(segU, 12);
      const sV = M.seg(segV, 8);
      const pos = [];
      for (let j = 0; j <= sV; j++) {
        const v = (j / sV) * Math.PI * 2;
        const cV = Math.cos(v);
        const sV_ = Math.sin(v);
        for (let i = 0; i <= sU; i++) {
          const u = (i / sU) * Math.PI * 2;
          const cU = Math.cos(u);
          const sU_ = Math.sin(u);
          const x = (radioMayor + radioMenor * cV) * cU;
          const y = (radioMayor + radioMenor * cV) * sU_;
          const z = radioMenor * sV_;
          pos.push(x, y, z);
        }
      }
      return M.coserNormales(rejilla(pos, sU, sV, nombre));
    }

    function almendra(rx, ry, rz, nombre = "Almendra", segA = 16, segB = 12) {
      const sW = M.seg(segA, 8);
      const sH = M.seg(segB, 6);
      const pos = [];
      for (let r = 0; r <= sH; r++) {
        const v = r / sH;
        const th = (v - 0.5) * Math.PI;
        const cTh = Math.cos(th);
        const sTh = Math.sin(th);
        const yN = ry * sTh;
        const ancho = cTh * (1 - 0.20 * Math.abs(sTh));
        for (let c = 0; c <= sW; c++) {
          const u = c / sW;
          const fi = u * Math.PI * 2;
          const sFi = Math.sin(fi);
          const cFi = Math.cos(fi);
          const xN = rx * ancho * cFi;
          const zN = rz * ancho * sFi;
          pos.push(xN, yN, zN);
        }
      }
      return M.coserNormales(rejilla(pos, sW, sH, nombre));
    }

    // ---------------- 1. ANATOMÍA Y EJE DEL OPHTHALMOSAURUS ----------------
    // Cuerpo fusiforme de ictiosaurio (assets/dinos/arte/agua/ophthalmosaurus_izq.webp)
    // [z, y, rw, rhA, rhB, p]
    const EJE = [
      [-0.74, 0.35, 0.000, 0.000, 0.000, 2.0],  // Base caudal entre lóbulos
      [-0.70, 0.35, 0.020, 0.035, 0.035, 2.0],  // Pedúnculo caudal distal
      [-0.60, 0.36, 0.055, 0.075, 0.070, 2.1],  // Pedúnculo caudal comprimido lateralmente
      [-0.45, 0.38, 0.125, 0.135, 0.130, 2.2],  // Cola anterior / zona pelviana
      [-0.25, 0.42, 0.190, 0.200, 0.195, 2.4],  // Lomo posterior / base de aleta dorsal
      [-0.05, 0.44, 0.220, 0.230, 0.225, 2.5],  // Pecho y barriga hidrodinámica profunda
      [ 0.15, 0.43, 0.205, 0.215, 0.210, 2.4],  // Hombros y base de aletas pectorales
      [ 0.30, 0.41, 0.170, 0.175, 0.170, 2.3],  // Nuca y transición suave de cabeza
      [ 0.42, 0.38, 0.135, 0.140, 0.130, 2.3],  // Cráneo y zona de los grandes ojos
      [ 0.54, 0.35, 0.085, 0.090, 0.080, 2.2],  // Base del hocico / rostro de delfín
      [ 0.64, 0.32, 0.050, 0.055, 0.045, 2.1],  // Rostro estilizado
      [ 0.70, 0.30, 0.025, 0.028, 0.022, 2.0],  // Punta del rostro
      [ 0.72, 0.30, 0.000, 0.000, 0.000, 2.0]   // Cierre hermético
    ];

    const ejeCurva = new THREE.CatmullRomCurve3(EJE.map(([z, y]) => V(0, y, z)), false, "centripetal");
    ejeCurva.arcLengthDivisions = 1200;
    const LARGO = ejeCurva.getLength();

    function seccion(u) {
      const f = ejeCurva.getUtoTmapping(u) * (EJE.length - 1);
      const i = Math.min(EJE.length - 2, Math.floor(f));
      const t = f - i;
      const a = EJE[Math.max(0, i - 1)];
      const b = EJE[i];
      const c = EJE[i + 1];
      const d = EJE[Math.min(EJE.length - 1, i + 2)];
      return [2, 3, 4, 5].map((j) => Math.max(0, cr(a[j], b[j], c[j], d[j], t)));
    }

    const X = V(1, 0, 0);
    function marcoEje(u) {
      const P = ejeCurva.getPointAt(u);
      const T = ejeCurva.getTangentAt(u);
      const ang = Math.atan2(T.y, T.z);
      const angSuave = ang * 0.28;
      const U = V(0, Math.cos(angSuave), -Math.sin(angSuave));
      return { P, T, U };
    }

    function uCercano(p, desde = 0, hasta = 1) {
      let mejor = desde;
      let dMin = Infinity;
      for (let k = 0; k <= 400; k++) {
        const u = desde + (hasta - desde) * (k / 400);
        const d = ejeCurva.getPointAt(u).distanceToSquared(p);
        if (d < dMin) { dMin = d; mejor = u; }
      }
      return mejor;
    }

    const COLS = M.seg(80, 24);
    const FILAS = M.seg(400, 70);
    const cuerpo = (() => {
      const pos = [];
      for (let r = 0; r <= FILAS; r++) {
        const u = r / FILAS;
        const { P, U } = marcoEje(u);
        const [w, hA, hB, p] = seccion(u);
        const ex = 2 / p;
        const z = P.z;

        // Quilla dorsal y ventral suave para hidrodinámica
        const quilla = (z > -0.45 && z < 0.20) ? 0.015 * Math.sin((z + 0.45) / 0.65 * Math.PI) : 0;

        for (let c = 0; c <= COLS; c++) {
          const fi = Math.PI + (c / COLS) * Math.PI * 2;
          const s = Math.sin(fi);
          const co = Math.cos(fi);
          const remateQuilla = co > 0.85 ? quilla * Math.pow((co - 0.85) / 0.15, 1.8) : 0;

          const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
          const ly = ((co >= 0 ? hA : hB) + remateQuilla) * Math.sign(co) * Math.pow(Math.abs(co), ex);
          const pto = P.clone().addScaledVector(X, lx).addScaledVector(U, ly);
          pos.push(pto.x, pto.y, pto.z);
        }
      }
      return M.coserNormales(rejilla(pos, COLS, FILAS, "CuerpoOphthalmo"));
    })();

    // ---------------- 2. ESQUELETO Y RIGGING ACUÁTICO ----------------
    const ALETA_DEL_X = 0.18;
    const ALETA_TRAS_X = 0.15;

    const HUESOS = [
      ["Raiz", null, 0, 0, 0],
      ["Cadera", "Raiz", 0, 0.40, -0.25],
      ["Cola1", "Cadera", 0, 0.38, -0.45],
      ["Cola2", "Cola1", 0, 0.36, -0.60],
      ["Cola3", "Cola2", 0, 0.35, -0.70],
      ["Pecho", "Cadera", 0, 0.44, 0.05],
      ["Cuello", "Pecho", 0, 0.42, 0.25],
      ["Cabeza", "Cuello", 0, 0.38, 0.42],
      ["Mandibula", "Cabeza", 0, 0.32, 0.42],

      // Aletas pectorales (delanteras)
      ["AletaDelI", "Pecho", ALETA_DEL_X, 0.36, 0.12],
      ["AletaPuntaDelI", "AletaDelI", ALETA_DEL_X + 0.10, 0.06, 0.04],
      ["AletaDelD", "Pecho", -ALETA_DEL_X, 0.36, 0.12],
      ["AletaPuntaDelD", "AletaDelD", -(ALETA_DEL_X + 0.10), 0.06, 0.04],

      // Aletas pelvianas (traseras)
      ["AletaTrasI", "Cadera", ALETA_TRAS_X, 0.33, -0.32],
      ["AletaPuntaTrasI", "AletaTrasI", ALETA_TRAS_X + 0.07, 0.06, -0.40],
      ["AletaTrasD", "Cadera", -ALETA_TRAS_X, 0.33, -0.32],
      ["AletaPuntaTrasD", "AletaTrasD", -(ALETA_TRAS_X + 0.07), 0.06, -0.40]
    ];

    const hueso = {};
    HUESOS.forEach(([nombre, padre, x, y, z]) => {
      const b = new THREE.Bone();
      b.name = "Hueso" + nombre;
      b.userData.reposo = V(x, y, z);
      const p = padre ? hueso[padre] : null;
      b.position.set(x, y, z).sub(p ? p.userData.reposo : V(0, 0, 0));
      (p || g).add(b);
      hueso[nombre] = b;
    });
    g.updateMatrixWorld(true);

    const colgar = (nombre, obj) => {
      const h = typeof nombre === "string" ? hueso[nombre] : nombre;
      if (!h || !obj) return obj;
      h.attach(obj);
      return obj;
    };

    const uH = (n, d1 = 0.2, d2 = 1) => uCercano(hueso[n].userData.reposo, d1, d2);
    const uCola3 = uCercano(hueso.Cola3.userData.reposo, 0, 0.35);
    const uCola2 = uCercano(hueso.Cola2.userData.reposo, 0.1, 0.45);

    const TRAMOS = [
      [0, "Cola3"],
      [uCola3, "Cola2"],
      [uCola2, "Cola1"],
      [uH("Cola1", 0.15, 0.45), "Cadera"],
      [uH("Pecho", 0.35, 0.60), "Pecho"],
      [uH("Cuello", 0.55, 0.75), "Cuello"],
      [uH("Cabeza", 0.70, 0.95), "Cabeza"]
    ];

    const MEZCLA = 0.20 / LARGO;
    function pesosTramos(u, tramos, mezcla) {
      let k = 0;
      while (k + 1 < tramos.length && u >= tramos[k + 1][0]) k++;
      const res = [[hueso[tramos[k][1]], 1]];
      if (k + 1 < tramos.length) {
        const w = suave(-mezcla, mezcla, u - tramos[k + 1][0]);
        if (w > 0) { res[0][1] = 1 - w; res.push([hueso[tramos[k + 1][1]], w]); }
      }
      if (k > 0) {
        const w = 1 - suave(-mezcla, mezcla, u - tramos[k][0]);
        if (w > 0) { res[0][1] *= 1 - w; res.push([hueso[tramos[k - 1][1]], w]); }
      }
      return res;
    }

    g.add(cuerpo);
    M.pielConHuesos(cuerpo, g, (i) => pesosTramos(Math.floor(i / (COLS + 1)) / FILAS, TRAMOS, MEZCLA));

    // ---------------- 3. ALETAS HIDRODINÁMICAS HERMÉTICAS 100% CERRADAS ----------------
    function aletaHidrodinamica(s, camino, radiosW, radiosH, huesosAleta, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(24, 10);
      const rSeg = M.seg(24, 10);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let rw = M.interp(radiosW, t);
        let rh = M.interp(radiosH, t);

        if (t < 0.20) {
          const cap = Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.20, 2)));
          rw *= cap;
          rh *= cap;
        }
        if (t > 0.85) {
          const tap = Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.85) / 0.15, 2)));
          rw *= tap;
          rh *= tap;
        }

        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          const lx = (pos.getX(k) - P.x) * rw;
          const ly = (pos.getY(k) - P.y) * rh;
          const lz = (pos.getZ(k) - P.z) * rw * 0.85;

          pos.setXYZ(k, P.x + lx, P.y + ly, P.z + lz);
        }
      }

      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      g.add(malla);

      const tramos = [
        [0, huesosAleta[0]],
        [0.55, huesosAleta[1]]
      ];
      M.pielConHuesos(malla, g, (i) => pesosTramos(Math.floor(i / (rSeg + 1)) / tSeg, tramos, 0.18));
      return malla;
    }

    LADOS.forEach((s) => {
      // Aleta pectoral delantera (pala hidrodinámica ancha y curva)
      const xDel = s * ALETA_DEL_X;
      aletaHidrodinamica(s,
        [
          [xDel * 0.90, 0.38, 0.12],
          [xDel * 1.15, 0.32, 0.10],
          [xDel * 1.40, 0.20, 0.06],
          [xDel * 1.55, 0.10, 0.03],
          [xDel * 1.60, 0.04, 0.01]
        ],
        [[0, 0.075], [0.25, 0.088], [0.55, 0.078], [0.85, 0.052], [1, 0.015]],
        [[0, 0.024], [0.25, 0.026], [0.55, 0.020], [0.85, 0.014], [1, 0.006]],
        ["AletaDel" + L(s), "AletaPuntaDel" + L(s)], "AletaPectoral");

      // Aleta pelviana trasera (pala hidrodinámica menor)
      const xTras = s * ALETA_TRAS_X;
      aletaHidrodinamica(s,
        [
          [xTras * 0.90, 0.34, -0.32],
          [xTras * 1.15, 0.28, -0.34],
          [xTras * 1.35, 0.18, -0.38],
          [xTras * 1.45, 0.08, -0.41],
          [xTras * 1.50, 0.03, -0.43]
        ],
        [[0, 0.055], [0.25, 0.062], [0.55, 0.054], [0.85, 0.036], [1, 0.012]],
        [[0, 0.018], [0.25, 0.020], [0.55, 0.015], [0.85, 0.010], [1, 0.005]],
        ["AletaTras" + L(s), "AletaPuntaTras" + L(s)], "AletaPelvica");
    });

    // ---------------- 4. ALETA DORSAL Y ALETA CAUDAL SEMILUNAR ----------------
    // Aleta dorsal hidrodinámica (forma de tiburón / delfín)
    function aletaVertical(camino, radiosW, radiosL, huesoNom, nombre) {
      const curva = M.curva(camino);
      const tSeg = M.seg(20, 8);
      const rSeg = M.seg(20, 8);
      const geo = new THREE.TubeGeometry(curva, tSeg, 1, rSeg, false);
      const pos = geo.attributes.position;
      const P = new THREE.Vector3();

      for (let i = 0; i <= tSeg; i++) {
        const t = i / tSeg;
        curva.getPointAt(t, P);
        let rw = M.interp(radiosW, t);
        let rl = M.interp(radiosL, t);

        if (t < 0.20) {
          const cap = Math.sqrt(Math.max(0, 1 - Math.pow(1 - t / 0.20, 2)));
          rw *= cap;
          rl *= cap;
        }
        if (t > 0.85) {
          const tap = Math.sqrt(Math.max(0, 1 - Math.pow((t - 0.85) / 0.15, 2)));
          rw *= tap;
          rl *= tap;
        }

        for (let j = 0; j <= rSeg; j++) {
          const k = i * (rSeg + 1) + j;
          const lx = (pos.getX(k) - P.x) * rw;
          const ly = (pos.getY(k) - P.y) * rw;
          const lz = (pos.getZ(k) - P.z) * rl;
          pos.setXYZ(k, P.x + lx, P.y + ly, P.z + lz);
        }
      }

      const malla = M.coserNormales(M.pieza(geo, nombre, rSeg, tSeg));
      colgar(huesoNom, malla);
      return malla;
    }

    // Aleta dorsal estilizada situada sobre el lomo
    aletaVertical([
      [0, 0.58, -0.15],
      [0, 0.65, -0.18],
      [0, 0.72, -0.21],
      [0, 0.77, -0.23]
    ],
    [[0, 0.035], [0.35, 0.024], [0.70, 0.014], [1, 0.004]],
    [[0, 0.120], [0.35, 0.095], [0.70, 0.065], [1, 0.015]],
    "Pecho", "AletaDorsal");

    // Aleta caudal vertical semilunar (lóbulo superior e inferior de ictiosaurio)
    // Lóbulo superior (curvado arriba y hacia atrás)
    aletaVertical([
      [0, 0.38, -0.65],
      [0, 0.46, -0.68],
      [0, 0.54, -0.71],
      [0, 0.60, -0.73]
    ],
    [[0, 0.028], [0.35, 0.020], [0.70, 0.012], [1, 0.003]],
    [[0, 0.080], [0.35, 0.065], [0.70, 0.045], [1, 0.012]],
    "Cola3", "LóbuloCaudalSuperior");

    // Lóbulo inferior (curvado abajo y hacia atrás)
    aletaVertical([
      [0, 0.32, -0.65],
      [0, 0.24, -0.68],
      [0, 0.16, -0.72],
      [0, 0.11, -0.74]
    ],
    [[0, 0.030], [0.35, 0.022], [0.70, 0.014], [1, 0.003]],
    [[0, 0.085], [0.35, 0.070], [0.70, 0.050], [1, 0.014]],
    "Cola3", "LóbuloCaudalInferior");

    // ---------------- 5. CABEZA, ROSTRO, MANDÍBULA Y OJOS ESCLERÓTICOS GIGANTES ----------------
    // Mandíbula inferior estilizada como pico de delfín
    const colsMand = M.seg(40, 18);
    const filasMand = M.seg(28, 14);
    const MAND_PERFIL = [
      [0.42, 0.320, 0.095, 0.024, 2.2],
      [0.52, 0.305, 0.075, 0.020, 2.2],
      [0.62, 0.285, 0.048, 0.016, 2.2],
      [0.68, 0.275, 0.025, 0.012, 2.1],
      [0.71, 0.270, 0.000, 0.000, 2.0]
    ];

    const posMand = [];
    for (let r = 0; r <= filasMand; r++) {
      const t = r / filasMand;
      const f = t * (MAND_PERFIL.length - 1);
      const i = Math.min(MAND_PERFIL.length - 2, Math.floor(f));
      const k = f - i;
      const a = MAND_PERFIL[Math.max(0, i - 1)];
      const b = MAND_PERFIL[i];
      const c = MAND_PERFIL[i + 1];
      const d = MAND_PERFIL[Math.min(MAND_PERFIL.length - 1, i + 2)];
      const [z, y, w, h, p] = [0, 1, 2, 3, 4].map((j) => cr(a[j], b[j], c[j], d[j], k));
      const ex = 2 / p;

      for (let col = 0; col <= colsMand; col++) {
        const fi = Math.PI + (col / colsMand) * Math.PI * 2;
        const s = Math.sin(fi);
        const co = Math.cos(fi);
        const lx = w * Math.sign(s) * Math.pow(Math.abs(s), ex);
        const ly = h * Math.sign(co) * Math.pow(Math.abs(co), ex);
        posMand.push(lx, y + ly, z);
      }
    }

    colgar("Mandibula", M.coserNormales(rejilla(posMand, colsMand, filasMand, "MandibulaOphthalmo")));
    colgar("Mandibula", bloque(0, 0.305, 0.54, 0.038, 0.010, 0.080, 0.6, "Lengua"));

    // Dientecitos finos cónicos de aguja
    LADOS.forEach((s) => {
      [0.48, 0.54, 0.60, 0.66].forEach((z, idx) => {
        const wTeeth = 0.082 - idx * 0.016;
        const xTeeth = s * wTeeth;
        colgar("Mandibula", punta([[xTeeth, 0.312, z], [xTeeth, 0.322, z + 0.001]], 0.004, "DienteInferior", 8, 6));
      });

      [0.49, 0.55, 0.61, 0.67].forEach((z, idx) => {
        const wTeeth = 0.086 - idx * 0.016;
        const xTeeth = s * wTeeth;
        colgar("Cabeza", punta([[xTeeth, 0.328, z], [xTeeth, 0.316, z + 0.001]], 0.0045, "DienteSuperior", 8, 6));
      });

      const labioPuntos = [
        [s * 0.110, 0.340, 0.44],
        [s * 0.095, 0.332, 0.52],
        [s * 0.075, 0.324, 0.60],
        [s * 0.045, 0.315, 0.66],
        [s * 0.005, 0.308, 0.70]
      ];
      colgar("Cabeza", M.tubo(labioPuntos, 0.005, 0.0035, { segLargo: 24, segRadio: 10, nombre: "LabioSuperior" }));
    });

    // Fosas nasales en la parte dorsal del rostro
    LADOS.forEach((s) => {
      colgar("Cabeza", bloque(s * 0.025, 0.365, 0.52, 0.006, 0.004, 0.008, 0.4, "FosaNasal", 10, 8));
    });

    // LOS ICÓNICOS Y ENORMES OJOS ESCLERÓTICOS DE OPHTHALMOSAURUS
    LADOS.forEach((s) => {
      const ojoGrupo = new THREE.Group();
      ojoGrupo.position.set(s * 0.138, 0.415, 0.395);
      ojoGrupo.rotation.y = s * 0.28;

      // Globo ocular blanco esférico amplio
      ojoGrupo.add(almendra(0.052, 0.048, 0.018, "OjoBlanco"));

      // Anillo esclerótico óseo característico (borde protector circular)
      const anillo = toroide(0.048, 0.0065, "AnilloEsclerotico", 24, 12);
      anillo.position.set(s * 0.002, 0, 0.008);
      ojoGrupo.add(anillo);

      // Iris anime celeste aguamarina profundo
      ojoGrupo.add(bloque(s * 0.004, 0, 0.007, 0.038, 0.038, 0.008, 1, "IrisAgua"));

      // Pupila redonda oscura profunda
      ojoGrupo.add(bloque(s * 0.004, -0.002, 0.012, 0.022, 0.024, 0.006, 1, "Pupila"));

      // Destellos luminosos anime
      ojoGrupo.add(bloque(-s * 0.012, 0.014, 0.016, 0.014, 0.014, 0.005, 1, "BrilloOjo"));
      ojoGrupo.add(bloque(s * 0.012, -0.012, 0.015, 0.007, 0.007, 0.004, 1, "BrilloOjoPequeno"));

      // Párpados estilizados
      ojoGrupo.add(M.tubo([
        [-0.046, 0.006, 0.008],
        [0, 0.044, 0.014],
        [0.046, 0.006, 0.008]
      ], 0.0055, 0.004, { segLargo: 12, segRadio: 8, nombre: "ParpadoSuperior" }));

      ojoGrupo.add(M.tubo([
        [-0.042, -0.006, 0.008],
        [0, -0.042, 0.012],
        [0.042, -0.006, 0.008]
      ], 0.005, 0.0035, { segLargo: 12, segRadio: 8, nombre: "ParpadoInferior" }));

      colgar("Cabeza", ojoGrupo);
    });

    // ---------------- 6. PINTURA: PROYECCIÓN Y COLORES DE OPHTHALMOSAURUS_IZQ.WEBP ----------------
    const TEXTURA = this.textura;
    const proyectar = M.proyeccion(TEXTURA, 1.05);

    const C_AZUL_BASE = new THREE.Color(0x3c555c);
    const C_BLANCO_VIENTRE = new THREE.Color(0xf2f6f7);
    const C_LENGUA = new THREE.Color(0xe07278);
    const C_ESCLEROTICO = new THREE.Color(0xdce8e6);
    const MARFIL = new THREE.Color(0xf4eedb);
    const cColor = new THREE.Color();

    // Pintura en zonas limpias (sin proyectar la ilustración, que dejaba el ojo dibujado y vetas sucias):
    // lomo pizarra oscuro, vientre blanco con límite suave y la franja blanca del ojo a la cola.
    const C_LOMO = new THREE.Color(0x34464e);
    const C_FRANJA = new THREE.Color(0xeef4f5);
    M.pintar(cuerpo, (i, p) => {
      const u = Math.floor(i / (COLS + 1)) / FILAS;
      const cIdx = i % (COLS + 1);
      const co = Math.cos(Math.PI + (cIdx / COLS) * Math.PI * 2);   // -1 panza … 1 lomo
      cColor.copy(C_BLANCO_VIENTRE).lerp(C_LOMO, suave(-0.22, -0.08, co));
      const franja = (1 - suave(0.04, 0.08, Math.abs(co - 0.22))) * suave(0.18, 0.26, u) * (1 - suave(0.74, 0.8, u));
      return cColor.lerp(C_FRANJA, franja);
    }, g);

    const COLOR_PIEZAS = {
      aletaPectoral: 0x3a4c54,
      aletaPelvica: 0x34464e,
      aletaDorsal: 0x354b52,
      mandibula: 0x3e575e,
      labio: 0x2d4248,
      fosaNasal: 0x1f2e33,
      parpado: 0x385057,
      anilloEsclerotico: 0xdce8e6,
      iris: 0x0ea5e9,
      pupila: 0x08151c,
      brillo: 0xffffff,
      ojoBlanco: 0xfdfdfd
    };

    const piezas = [];
    g.traverse((o) => { if (o.isMesh && o !== cuerpo) piezas.push(o); });

    piezas.forEach((o) => {
      if (/^(Diente)/.test(o.name)) return M.pintar(o, () => MARFIL, g);
      if (o.name === "AnilloEsclerotico") return M.pintar(o, () => C_ESCLEROTICO, g);
      if (o.name === "Lengua") return M.pintar(o, () => C_LENGUA, g);
      if (o.name === "OjoBlanco") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.ojoBlanco), g);
      if (o.name === "IrisAgua") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.iris), g);
      if (o.name === "Pupila") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.pupila), g);
      if (/^BrilloOjo/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.brillo), g);
      if (/^Parpado/.test(o.name)) return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.parpado), g);
      if (o.name === "LabioSuperior") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.labio), g);
      if (o.name === "FosaNasal") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.fosaNasal), g);

      if (o.name === "MandibulaOphthalmo") return M.pintar(o, () => C_BLANCO_VIENTRE, g);
      if (o.name === "AletaPectoral") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.aletaPectoral), g);
      if (o.name === "AletaPelvica") return M.pintar(o, () => new THREE.Color(COLOR_PIEZAS.aletaPelvica), g);
      M.pintar(o, () => C_LOMO, g);
    });

    // ---------------- 7. ANIMACIONES SUBACUÁTICAS (NADO PELÁGICO FLUIDO) ----------------
    function giro(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const q = new THREE.Quaternion();
      const eu = new THREE.Euler(0, 0, 0, "YXZ");
      for (let i = 0; i <= n; i++) {
        const [x, y, z] = fn(i / n);
        eu.set(x * grad, y * grad, z * grad);
        q.setFromEuler(eu);
        tiempos.push(i * (dur / n));
        valores.push(q.x, q.y, q.z, q.w);
      }
      return new THREE.QuaternionKeyframeTrack("Hueso" + nombre + ".quaternion", tiempos, valores);
    }

    function sube(nombre, dur, fn, n = 32) {
      const tiempos = [];
      const valores = [];
      const [x0, y0, z0] = hueso[nombre].position.toArray();
      for (let i = 0; i <= n; i++) {
        tiempos.push(i * (dur / n));
        valores.push(x0, y0 + fn(i / n), z0);
      }
      return new THREE.VectorKeyframeTrack("Hueso" + nombre + ".position", tiempos, valores);
    }

    const sen = (t, c = 1) => Math.sin(t * Math.PI * 2 * c);
    const cos = (t, c = 1) => Math.cos(t * Math.PI * 2 * c);

    const dR = 3.6;
    const reposo = new THREE.AnimationClip("Reposo", dR, [
      sube("Cadera", dR, (t) => 0.010 * sen(t)),
      giro("Cadera", dR, (t) => [0, 2.0 * sen(t), 1.0 * cos(t)]),
      giro("Pecho", dR, (t) => [0, -1.5 * sen(t), -1.0 * cos(t)]),
      giro("Cuello", dR, (t) => [0, -1.0 * sen(t), 0]),
      giro("Cabeza", dR, (t) => [1.0 * cos(t), 1.5 * sen(t), 0]),
      giro("Cola1", dR, (t) => [0, 4.0 * sen(t), 0]),
      giro("Cola2", dR, (t) => [0, 7.0 * sen(t), 0]),
      giro("Cola3", dR, (t) => [0, 10.0 * sen(t), 0]),
      ...LADOS.flatMap((s) => [
        giro("AletaDel" + L(s), dR, (t) => [3.0 * sen(t), 0, s * (4.0 * cos(t))]),
        giro("AletaTras" + L(s), dR, (t) => [2.0 * sen(t), 0, s * (3.0 * cos(t))])
      ])
    ]);

    const dN = 1.8;
    const ONDA = 24;
    const nadar = new THREE.AnimationClip("Nadar", dN, [
      sube("Cadera", dN, (t) => 0.015 * sen(t, 2)),
      giro("Cadera", dN, (t) => [1.5 * sen(t, 2), 6 * sen(t), 3 * cos(t)]),
      giro("Pecho", dN, (t) => [-1.5 * sen(t, 2), -5 * sen(t), -2 * cos(t)]),
      giro("Cuello", dN, (t) => [1.0 * sen(t, 2), 3 * sen(t), 0]),
      giro("Cabeza", dN, (t) => [-1.0 * sen(t, 2), -4 * sen(t), 0]),
      // Propulsión caudal potente sinusoidal en Y (vaivén lateral tipo pez/ictiosaurio)
      giro("Cola1", dN, (t) => [0, -ONDA * 0.40 * sen(t), 0]),
      giro("Cola2", dN, (t) => [0, -ONDA * 0.75 * sen(t - 0.12), 0]),
      giro("Cola3", dN, (t) => [0, -ONDA * 1.15 * sen(t - 0.24), 0]),
      ...LADOS.flatMap((s) => [
        giro("AletaDel" + L(s), dN, (t) => [12 * cos(t), -6 * sen(t), s * (16 * sen(t))]),
        giro("AletaPuntaDel" + L(s), dN, (t) => [8 * cos(t), 0, s * (10 * sen(t))]),
        giro("AletaTras" + L(s), dN, (t) => [8 * cos(t), -4 * sen(t), s * (10 * sen(t))])
      ])
    ]);

    const dG = 2.2;
    const arqueo = [[0, 0], [0.25, 1], [0.75, 1], [1, 0]];
    const abrirBoca = [[0, 0], [0.22, 0], [0.42, 1], [0.72, 1], [0.88, 0], [1, 0]];
    const rugir = new THREE.AnimationClip("Rugir", dG, [
      sube("Cadera", dG, (t) => 0.035 * M.interp(arqueo, t)),
      giro("Cadera", dG, (t) => [-10 * M.interp(arqueo, t), 0, 0]),
      giro("Pecho", dG, (t) => [12 * M.interp(arqueo, t), 0, 0]),
      giro("Cuello", dG, (t) => [15 * M.interp(arqueo, t), 0, 0]),
      giro("Cabeza", dG, (t) => [10 * M.interp(arqueo, t), 0, 0]),
      giro("Mandibula", dG, (t) => [28 * M.interp(abrirBoca, t), 0, 0]),
      giro("Cola1", dG, (t) => [0, 16 * sen(t, 2), 0]),
      giro("Cola2", dG, (t) => [0, 26 * sen(t, 2), 0]),
      giro("Cola3", dG, (t) => [0, 36 * sen(t, 2), 0]),
      ...LADOS.flatMap((s) => [
        giro("AletaDel" + L(s), dG, (t) => [-20 * M.interp(arqueo, t), 0, s * 14]),
        giro("AletaTras" + L(s), dG, (t) => [-12 * M.interp(arqueo, t), 0, s * 8])
      ])
    ]);

    g.animations = [reposo, nadar, rugir];
    hueso.Raiz.userData.esqueleto = HUESOS.map(([nombre]) => "Hueso" + nombre);

    return g;
  },

  textura: {
    w: 260, h: 137, k: 2, esc: 0.00285, x0: 265, y0: 275,
    datos: ""
  }
});
